const CACHE='khadamat-shell-v2-11';
const SHELL=['/','/customer','/customer.html','/provider','/provider.html','/admin','/admin.html','/css/app.css','/js/app.js','/manifest.webmanifest','/manifest-customer.webmanifest','/manifest-provider.webmanifest','/manifest-admin.webmanifest','/js/install-app.js','/icons/icon-customer-192.png','/icons/icon-customer-512.png','/icons/icon-provider-192.png','/icons/icon-provider-512.png','/icons/icon-admin-192.png','/icons/icon-admin-512.png'];
self.addEventListener('install',e=>e.waitUntil(caches.open(CACHE).then(c=>c.addAll(SHELL)).then(()=>self.skipWaiting())));
self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('khadamat-shell-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',e=>{const u=new URL(e.request.url);if(e.request.method!=='GET'||u.origin!==self.location.origin||u.pathname.startsWith('/api/'))return;const networkFirst=e.request.mode==='navigate'||['/js/app.js','/css/app.css','/sw.js'].includes(u.pathname)||u.pathname.startsWith('/manifest');if(networkFirst){e.respondWith(fetch(e.request).then(r=>{if(r.ok){const copy=r.clone();caches.open(CACHE).then(c=>c.put(e.request,copy)).catch(()=>{});}return r;}).catch(()=>caches.match(e.request).then(cached=>cached||Response.error())));return;}e.respondWith(caches.match(e.request).then(cached=>cached||fetch(e.request).then(r=>{if(r.ok){const copy=r.clone();caches.open(CACHE).then(c=>c.put(e.request,copy)).catch(()=>{});}return r;})));});

self.addEventListener('push', event => { let data={}; try{data=event.data?event.data.json():{};}catch{data={body:event.data?event.data.text():''};} const title=data.title||'خدمات'; const options={body:data.body||'لديك إشعار جديد',icon:'/icons/icon-192.png',data:data.data||{}}; event.waitUntil(self.registration.showNotification(title,options)); });
self.addEventListener('notificationclick', event => { event.notification.close(); const orderId=event.notification.data?.orderId; const chat=event.notification.data?.open==='chat'; const page=event.notification.data?.targetPage||'/customer'; const target=orderId?`${page}?order=${encodeURIComponent(orderId)}${chat?'&chat=1':''}`:page; event.waitUntil(clients.matchAll({type:'window',includeUncontrolled:true}).then(list=>{for(const c of list){if('focus' in c){c.navigate(target);return c.focus();}} return clients.openWindow(target);})); });
